*{box-sizing:border-box} :root{--bg:#0d1214;--panel:#131a1d;--panel2:#182124;--line:#263236;--muted:#758488;--text:#e5ece8;--accent:#d7ad59;--green:#94c98a;--red:#e27768;--mono:'DM Mono',monospace;--display:'Barlow Condensed',sans-serif}html,body{margin:0;width:100%;height:100%;background:#0b1012;color:var(--text);font-family:Inter,Arial,sans-serif;overflow:hidden}.game-shell{height:100dvh;min-height:600px;display:flex;flex-direction:column;background:radial-gradient(ellipse at 58% 45%,#20292b 0,#12191b 55%,#0d1214 100%)}.topbar{height:74px;flex-shrink:0;border-bottom:1px solid #293438;display:flex;align-items:center;padding:0 24px;gap:32px;background:rgba(12,17,19,.96);z-index:5}.brand{display:flex;align-items:center;gap:12px;width:275px;flex-shrink:0}.brand-mark{width:34px;height:34px;display:flex;align-items:center;justify-content:center;gap:2px;transform:skew(-14deg);border:1px solid #a68d58;padding:6px}.brand-mark span{display:block;width:4px;background:var(--accent);height:18px}.brand-mark span:nth-child(2){height:23px}.brand-mark span:nth-child(3){height:13px}.brand-name{font:800 21px/19px var(--display);letter-spacing:1.6px;color:#e5e9e5}.brand-name span{color:var(--accent);margin-left:5px}.brand-sub,.eyebrow{font:10px var(--mono);letter-spacing:1.1px;color:#7f908e}.brand-sub{font-size:8px;letter-spacing:1.35px;margin-top:5px}.resources{height:100%;display:flex;align-items:center;gap:34px;flex:1}.resource{display:flex;align-items:center;gap:10px;min-width:94px}.res-icon{font-size:18px;width:26px;height:26px;display:grid;place-items:center}.res-icon.alloy{color:#d7ad59}.res-icon.energy{color:#82bdd0;font-size:23px}.res-icon.intel{color:#a7ad8a}.resource div{display:flex;flex-direction:column;gap:1px}.resource small{font:9px var(--mono);letter-spacing:1px;color:#7f908e}.resource strong{font:600 16px var(--mono);letter-spacing:.3px}.resource em{font:10px var(--mono);font-style:normal;color:#85b67b;align-self:flex-end;margin-left:-4px;margin-bottom:3px}.top-actions{display:flex;align-items:center;gap:10px}.mission-clock{display:grid;grid-template-columns:8px 45px auto;align-items:center;column-gap:7px;margin-right:12px}.mission-clock>span:nth-child(2){font:12px var(--mono)}.mission-clock small{font:8px var(--mono);letter-spacing:.7px;color:#8a9996;grid-column:2/4;margin-top:3px}.live-dot{height:6px;width:6px;border-radius:100%;background:#80c27a;box-shadow:0 0 8px #80c27a}.icon-btn{width:34px;height:34px;background:#1a2426;color:#bdc8c3;border:1px solid #354245;font:16px var(--mono);cursor:pointer}.icon-btn:hover,.tool-btn:hover{border-color:var(--accent);color:var(--accent)}.speed-btn{font-size:11px;width:40px}
.main-layout{display:grid;grid-template-columns:268px minmax(400px,1fr) 260px;gap:0;min-height:0;flex:1}.left-panel,.right-panel{background:rgba(16,23,25,.94);position:relative;z-index:2;min-height:0}.left-panel{border-right:1px solid var(--line);padding:21px 18px 14px;display:flex;flex-direction:column}.right-panel{border-left:1px solid var(--line);padding:20px 17px 14px;display:flex;flex-direction:column}.panel-heading{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.panel-heading h1{font:700 25px/1 var(--display);letter-spacing:1px;margin:6px 0 0}.panel-heading h1 b{color:var(--accent)}.status-pill{font:8px var(--mono);color:#90c38b;border:1px solid #3c6340;padding:5px 7px;letter-spacing:.6px}.status-pill i{display:inline-block;width:5px;height:5px;border-radius:50%;background:#90c38b;margin-right:4px;vertical-align:1px}.objective-card{background:linear-gradient(110deg,#252b27,#1b2322);border:1px solid #3d4438;padding:12px 10px;display:flex;align-items:flex-start;gap:10px;margin-bottom:19px}.objective-icon{font-size:22px;color:var(--accent);width:29px;height:29px;border:1px solid #665b3c;display:grid;place-items:center;flex:none}.objective-card strong{display:block;font:600 12px Inter;margin-top:5px}.objective-card p{font-size:10px;line-height:1.5;color:#9daaa4;margin:5px 0 0}.section-title{display:flex;align-items:center;justify-content:space-between;font:9px var(--mono);letter-spacing:.9px;color:#8c9a97;margin:0 0 12px}.section-title>i{height:1px;background:#273437;flex:1;margin-left:10px}.intel-row{display:flex;justify-content:space-between;align-items:center;font:9px var(--mono);color:#879592;margin:0 0 9px}.intel-row strong{font:9px var(--mono);color:#d59c66}.danger-text{color:#d98e69!important}.threat-meter{display:flex;gap:3px;margin:0 0 15px}.threat-meter span{height:4px;flex:1;background:#d38d5e}.threat-meter span.dim{background:#37403d}.squads-title{margin-top:5px;margin-bottom:9px}.squads-title span:last-child{font-size:8px;color:#7e8d89}.squad-list{display:flex;flex-direction:column;gap:6px;max-height:150px;overflow:auto}.squad-row{display:grid;grid-template-columns:32px 1fr auto;align-items:center;gap:8px;border:1px solid #263236;padding:6px;background:#151d1f;cursor:pointer}.squad-row:hover,.squad-row.active{border-color:#957c4e;background:#202524}.squad-icon{height:28px;width:31px;background:#29312d;display:grid;place-items:center;color:#b1bf9b;font:17px var(--display)}.squad-meta strong{font:600 10px Inter;display:block}.squad-meta small{font:8px var(--mono);color:#84928d;display:block;margin-top:4px}.squad-health{width:40px;height:3px;background:#3c4741}.squad-health i{display:block;height:100%;background:#8cbe78}.log-title{margin-top:17px;margin-bottom:7px}.log-live{color:#7dba79;font-size:8px}.event-log{font:9px/1.6 var(--mono);color:#8f9b96;overflow:auto;flex:1;min-height:45px}.log-entry{border-left:1px solid #3d5148;padding-left:7px;margin:0 0 6px}.log-entry b{color:#c3a467;font-weight:400}.side-footer{border-top:1px solid #253134;padding-top:10px;margin-top:10px;color:#64736f;font:8px var(--mono);letter-spacing:.6px}.signal-icon{color:#79aa78;margin-right:5px}.footer-right{float:right}
.battlefield-wrap{min-width:0;display:flex;flex-direction:column;position:relative;background:#141a19}.battlefield-header{height:48px;display:flex;justify-content:space-between;align-items:center;padding:0 17px;border-bottom:1px solid #293335;background:#151c1d;z-index:1}.map-label{display:flex;align-items:center;gap:7px;font:10px var(--mono);letter-spacing:1px;color:#d0d8d1}.map-label small{font:8px var(--mono);color:#75837e;border-left:1px solid #384340;padding-left:8px;margin-left:4px}.map-cross{color:var(--accent);font-size:17px}.map-tools{display:flex;align-items:center;gap:14px}.control-hint{font:8px var(--mono);color:#71807b}.control-hint kbd,.build-card kbd{font:8px var(--mono);color:#a9b5ad;border:1px solid #46514b;padding:2px 4px;margin-right:4px;background:#1b2422}.tool-btn{border:1px solid #394543;color:#afbbb5;background:#1b2424;width:28px;height:26px;font-size:17px;cursor:pointer}.canvas-frame{position:relative;flex:1;min-height:200px;overflow:hidden;background:#272b26}#battlefield{display:block;width:100%;height:100%;cursor:crosshair}.map-vignette{position:absolute;inset:0;pointer-events:none;box-shadow:inset 0 0 95px 15px rgba(8,12,11,.5)}.map-coordinates{position:absolute;pointer-events:none;color:rgba(210,216,197,.45);font:8px var(--mono);letter-spacing:1px}.top-left{left:16px;top:14px}.bottom-right{right:17px;bottom:15px}.bottom-right span{color:#ddbd70;font-size:12px}.battlefield-footer{height:39px;background:#141b1c;border-top:1px solid #303a39;display:flex;justify-content:space-between;align-items:center;padding:0 15px}.selection-info{display:flex;align-items:center;gap:8px;font:9px var(--mono);color:#c3cec6}.selection-dot{width:6px;height:6px;background:#d8b15e;border-radius:50%;box-shadow:0 0 7px #d8b15e}.selection-sub{color:#71807a;border-left:1px solid #394340;padding-left:8px}.terrain-info{display:flex;align-items:center;gap:8px;font:8px var(--mono);color:#788782}.terrain-info strong{color:#bcc5bd;font-size:8px}.weather-icon{font-size:14px;color:#acb3a5}
.command-bar{height:112px;background:#111819;border-top:1px solid #293536;display:flex;align-items:center;padding:12px 17px;gap:19px;z-index:2}.command-info{display:flex;flex-direction:column;gap:6px;width:105px;flex:none}.command-info strong{font:700 15px var(--display);letter-spacing:.8px}.build-options{display:flex;gap:7px;flex:1}.build-card{position:relative;width:105px;height:84px;flex:1;max-width:139px;min-width:80px;text-align:left;background:#1a2323;border:1px solid #37413c;color:#e0e6df;padding:5px 7px;cursor:pointer;transition:.15s}.build-card:hover{border-color:#b49558;background:#242b27;transform:translateY(-2px)}.build-card.disabled{opacity:.42}.build-card kbd{position:absolute;right:4px;top:4px;padding:1px 3px}.build-art{height:36px;width:100%;position:relative;display:block;margin-bottom:3px;overflow:hidden;background:linear-gradient(135deg,#252d29,#1c2523)}.build-art:after{content:'';position:absolute;left:0;right:0;bottom:3px;height:1px;background:#3c4840}.rifle-art i{position:absolute;bottom:6px;left:25%;width:5px;height:14px;border-radius:4px 4px 1px 1px;background:#9aa68b;box-shadow:0 5px 0 -1px #788378}.rifle-art i:nth-child(2){left:48%;height:18px}.rifle-art i:nth-child(3){left:69%;height:13px}.scout-art i{position:absolute;left:36%;bottom:7px;width:34px;height:13px;background:#87917d;clip-path:polygon(15% 0,75% 0,100% 50%,88% 100%,0 100%,0 35%)}.scout-art i:after{content:'';position:absolute}.turret-art i{position:absolute;left:43%;bottom:8px;width:24px;height:17px;border-radius:4px 4px 2px 2px;background:#9a8b61}.turret-art i:before{content:'';position:absolute;width:3px;height:19px;background:#b9a268;top:-12px;left:10px;transform:rotate(38deg)}.extractor-art i{position:absolute;left:38%;bottom:7px;width:29px;height:21px;background:linear-gradient(90deg,#7e9a80 45%,#9fb58d 45%,#9fb58d 56%,#6e836e 56%);clip-path:polygon(0 100%,0 42%,20% 42%,20% 14%,37% 14%,37% 0,58% 0,58% 28%,83% 28%,83% 100%)}.build-name{font:700 10px var(--display);letter-spacing:.5px;display:block;white-space:nowrap}.build-cost{display:flex;gap:7px;margin-top:3px}.build-cost b{font:8px var(--mono);color:#b4c0b7}.build-cost b:first-child{color:#d7b266}.command-help{width:111px;flex:none;display:grid;grid-template-columns:auto;gap:2px;padding-left:12px;border-left:1px solid #303b39;font:8px var(--mono);color:#92a098}.command-help span:not(.help-divider){color:#c2cbbf}.command-help small{font:7px var(--mono);color:#71807b}.help-divider{height:1px;width:100%;background:#293532;margin:3px 0}
.radar-heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:12px}.radar-heading strong{display:block;font:700 16px var(--display);letter-spacing:.9px;margin-top:4px}.radar-status{font:8px var(--mono);color:#90c38b;letter-spacing:1px}.radar-wrap{position:relative;height:155px;background:#18211e;border:1px solid #35413a;overflow:hidden}.radar-wrap canvas{width:100%;height:100%;display:block}.radar-scan{position:absolute;inset:0;background:linear-gradient(180deg,transparent 48%,rgba(153,195,131,.08) 50%,transparent 53%);animation:scan 5s linear infinite;pointer-events:none}.radar-corner{position:absolute;width:7px;height:7px;border-color:#c3a765}.tl{left:-1px;top:-1px;border-left:1px solid;border-top:1px solid}.tr{right:-1px;top:-1px;border-right:1px solid;border-top:1px solid}.bl{left:-1px;bottom:-1px;border-left:1px solid;border-bottom:1px solid}.br{right:-1px;bottom:-1px;border-right:1px solid;border-bottom:1px solid}@keyframes scan{from{transform:translateY(-100%)}to{transform:translateY(100%)}}.map-legend{display:flex;gap:17px;margin:10px 0 19px;font:8px var(--mono);color:#89958f}.map-legend i{display:inline-block;width:6px;height:6px;border-radius:50%;margin-right:5px}.legend-friendly{background:#a9d494}.legend-hostile{background:#ed7968}.structure-title{margin:0 0 10px}.base-online{font-size:8px;color:#88b884}.base-card{border:1px solid #2e3a37;padding:9px;display:flex;gap:9px;background:#161f1f;margin-bottom:17px}.base-thumb{height:44px;width:49px;flex:none;background:linear-gradient(145deg,#29342d,#1d2825);display:grid;place-items:center;position:relative;color:#c3a765;font-size:26px}.base-thumb i{position:absolute;width:28px;height:2px;bottom:7px;background:#779176}.base-detail{flex:1;min-width:0}.base-detail strong{font:700 10px var(--display);letter-spacing:.4px;display:block}.base-detail small{font:7px var(--mono);color:#7f8e87;display:block;margin-top:3px}.health-track{height:3px;background:#414a43;margin-top:7px}.health-track i{height:100%;width:100%;display:block;background:#89b978}.health-label{font:7px var(--mono);color:#71807a;display:flex;justify-content:space-between;margin-top:4px}.health-label b{color:#9bc38c;font-weight:400}.power-card{border:1px solid #2d3837;background:#161e1e;padding:9px;margin-bottom:17px}.power-row{display:flex;justify-content:space-between;font:8px var(--mono);color:#82908a;margin-bottom:7px}.power-row b{font:8px var(--mono);color:#b8c2b9}.power-row b:first-letter{color:#8eb77d}.power-bar{height:4px;background:#35413b;margin:3px 0 6px}.power-bar i{display:block;height:100%;width:72%;background:linear-gradient(90deg,#80ad78,#d5ba69)}.power-card>small{font:7px var(--mono);color:#718078}.power-card>small b{float:right;color:#a8b3aa;font-weight:400}.control-percent{font:10px var(--mono);color:#d1b05f}.control-track{height:5px;background:#323d39}.control-track i{height:100%;width:18%;display:block;background:#c4a45d;transition:width .5s}.control-copy{font:9px/1.5 Inter;color:#7f8d86;margin:7px 0}.right-footer{margin-top:auto;border-top:1px solid #293433;padding-top:10px;display:flex;justify-content:space-between;font:7px var(--mono);color:#596864;letter-spacing:.4px}
.toast{position:absolute;top:18px;left:50%;transform:translate(-50%,-10px);background:#17201f;border:1px solid #877448;color:#e0c47e;padding:9px 14px;font:10px var(--mono);letter-spacing:.5px;opacity:0;pointer-events:none;transition:.2s;z-index:4;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.pause-overlay{display:none;position:absolute;inset:0;z-index:3;align-items:center;justify-content:center;flex-direction:column;background:rgba(9,14,14,.62);backdrop-filter:blur(2px);color:#dbc27f}.pause-overlay.show{display:flex}.pause-overlay div{font-size:33px}.pause-overlay strong{font:700 20px var(--display);letter-spacing:2px;margin-top:7px}.pause-overlay span{font:9px var(--mono);color:#a5afa5;margin-top:8px}.build-modal{position:fixed;inset:0;background:#080d0dcc;display:none;place-items:center;z-index:10}.build-modal.open{display:grid}.modal-card{width:min(380px,calc(100vw - 32px));background:#182120;border:1px solid #786743;box-shadow:0 20px 80px #000;padding:23px}.modal-card>strong{display:block;font:700 22px var(--display);letter-spacing:1px;margin-top:7px}.modal-card p{font-size:11px;line-height:1.6;color:#9aa69e;margin:9px 0 20px}.modal-actions{display:flex;justify-content:flex-end;gap:8px}.modal-actions button{border:1px solid #3e4a43;background:#202a27;color:#cad2c9;padding:9px 12px;font:9px var(--mono);cursor:pointer}.modal-actions .confirm-btn{background:#a2864e;border-color:#bd9d5d;color:#101613;font-weight:500}.modal-actions button:hover{filter:brightness(1.15)}.mobile-controls{display:none}
@media(max-width:1100px){.main-layout{grid-template-columns:225px minmax(330px,1fr) 220px}.left-panel{padding:16px 13px}.right-panel{padding:16px 12px}.topbar{padding:0 16px;gap:17px}.brand{width:230px}.resources{gap:15px}.command-bar{gap:11px;padding:10px}.command-info{width:90px}.command-help{width:90px;padding-left:8px}.build-card{min-width:69px;padding:5px}.build-name{font-size:9px}}
@media(max-width:800px){html,body{overflow:auto}.game-shell{height:auto;min-height:100dvh}.topbar{height:60px;padding:0 12px;gap:8px}.brand{width:auto;flex:1}.brand-mark{width:29px;height:29px}.brand-name{font-size:18px}.brand-sub{font-size:7px}.resources{justify-content:flex-end;gap:12px;flex:0}.resource{min-width:auto;gap:4px}.resource .res-icon{font-size:15px;width:18px}.resource div small{font-size:7px}.resource strong{font-size:12px}.resource em{display:none}.resource:nth-child(3){display:none}.top-actions{gap:5px}.mission-clock{grid-template-columns:6px auto;margin:0 3px;column-gap:4px}.mission-clock small{display:none}.mission-clock>span:nth-child(2){font-size:10px}.icon-btn{width:30px;height:30px}.main-layout{display:flex;flex-direction:column;min-height:calc(100dvh - 60px)}.left-panel,.right-panel{display:none}.battlefield-wrap{height:calc(100dvh - 60px);min-height:570px}.battlefield-header{height:39px;padding:0 10px}.map-label{font-size:9px}.map-tools{gap:6px}.control-hint{display:none}.battlefield-footer{height:34px;padding:0 9px}.selection-info{font-size:8px;gap:6px}.selection-sub{font-size:8px}.terrain-info{display:none}.command-bar{height:auto;min-height:110px;padding:8px;gap:7px;align-items:stretch;flex-direction:column}.command-info{width:auto;flex-direction:row;align-items:center;justify-content:space-between}.command-info .eyebrow{font-size:8px}.command-info strong{font-size:12px}.build-options{gap:5px}.build-card{height:65px;min-width:0;padding:4px}.build-art{height:27px}.build-name{font-size:8px}.build-cost{gap:3px}.build-cost b{font-size:7px}.build-card kbd{display:none}.command-help{display:none}.mobile-controls{display:flex;position:absolute;bottom:133px;left:12px;flex-direction:column;gap:4px;opacity:.72}.mobile-controls>button,.mobile-controls div button{background:#17201ed9;color:#ced5ca;border:1px solid #65715e;border-radius:4px;width:34px;height:30px}.mobile-controls div{display:flex;gap:4px}.canvas-frame{min-height:0}.map-coordinates{font-size:7px}}
@media(max-width:390px){.brand-name{font-size:15px}.brand-sub{font-size:6px}.resources{gap:6px}.resource strong{font-size:11px}.build-cost b{font-size:6px}.build-name{font-size:7px}.build-art{height:24px}}

(() => {
  const canvas = document.getElementById('battlefield');
  const ctx = canvas.getContext('2d');
  const mini = document.getElementById('minimap');
  const mctx = mini.getContext('2d');
  const WORLD = { w: 1500, h: 960 };
  const ui = Object.fromEntries(['alloy','energy','intel','alloy-rate','energy-rate','clock','wave-countdown','unit-count','squad-list','event-log','selection-label','selection-sub','base-health','base-health-label','power-generation','power-use','power-state','control-percent','control-bar','toast','pause-overlay','build-modal','modal-title','modal-copy','confirm-build','cancel-build','pause-btn','speed-btn','center-btn'].map(id => [id, document.getElementById(id)]));
  const state = { alloy:650, energy:280, intel:0, elapsed:0, paused:false, speed:1, camera:{x:650,y:480}, zoom:1, selected:[], placing:null, mouse:{x:0,y:0}, drag:null, projectiles:[], effects:[], notices:[], nextWave:150, wave:0, gameOver:false, baseHealth:100, enemyBaseHealth:100, lastTime:performance.now(), recruitCooldown:0 };
  let W=800,H=600,DPR=1;
  const rand=(a,b)=>a+Math.random()*(b-a), clamp=(n,a,b)=>Math.max(a,Math.min(b,n)), dist=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
  const units=[], buildings=[], decor=[], selectedIds=new Set();
  let uid=0;
  const makeUnit=(type,x,y,team='blue')=>{
    const data={rifle:{name:'RIFLE SQUAD',hp:100,speed:45,range:145,damage:12,rate:1.05,size:14,icon:'✣'},scout:{name:'SCOUT BUGGY',hp:155,speed:72,range:175,damage:18,rate:.8,size:18,icon:'▰'},raider:{name:'RAIDER TEAM',hp:100,speed:40,range:135,damage:10,rate:1.2,size:13,icon:'✣'},tank:{name:'STRIDER',hp:220,speed:32,range:195,damage:25,rate:1.3,size:22,icon:'⬟'}}[type];
    const u={id:++uid,type,x,y,team,...data,maxHp:data.hp,attackTimer:rand(.1,.8),target:null,moveTarget:null,selected:false,angle:0};units.push(u);return u;
  };
  const makeBuilding=(type,x,y,team='blue')=>{
    const d={base:{name:'COMMAND RELAY',hp:900,size:44,range:190,damage:17,rate:1.1},enemyBase:{name:'HOSTILE CORE',hp:900,size:48,range:190,damage:18,rate:1.05},turret:{name:'AUTOCANNON',hp:300,size:23,range:220,damage:23,rate:.8},extractor:{name:'ALLOY EXTRACTOR',hp:210,size:25,range:0,damage:0,rate:0}}[type];
    const b={id:++uid,type,x,y,team,...d,maxHp:d.hp,attackTimer:rand(.1,.6),selected:false};buildings.push(b);return b;
  };
  makeBuilding('base',220,480);makeBuilding('enemyBase',1300,480,'red');
  [makeUnit('rifle',335,440),makeUnit('rifle',355,480),makeUnit('scout',330,520)].forEach(u=>u.rally='');
  // Seed the hostile perimeter and natural cover with a stable layout.
  for(let i=0;i<20;i++) makeUnit(i%6===0?'tank':'raider',rand(900,1190),rand(220,740),'red');
  let seed=8129;const random=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296};
  for(let i=0;i<150;i++){const x=80+random()*1340,y=45+random()*870;if((x<440&&y>370&&y<600)||(x>1080&&y>370&&y<600))continue;decor.push({x,y,type:random()<.58?'rock':random()<.5?'scrub':'wreck',s:.45+random()*1.4,rot:random()*6.28,shade:Math.floor(random()*4)});}

  function resize(){const r=canvas.getBoundingClientRect();DPR=Math.min(devicePixelRatio||1,2);W=Math.max(1,r.width);H=Math.max(1,r.height);canvas.width=Math.floor(W*DPR);canvas.height=Math.floor(H*DPR);ctx.setTransform(DPR,0,0,DPR,0,0);}
  new ResizeObserver(resize).observe(canvas);resize();
