  function formatTime(t){return`${String(Math.floor(t/60)).padStart(2,'0')}:${String(Math.floor(t%60)).padStart(2,'0')}`}
  function resource(cost){if(state.alloy<cost[0]||state.energy<cost[1]){notify('INSUFFICIENT FIELD RESOURCES');return false}state.alloy-=cost[0];state.energy-=cost[1];return true}
  function costText(type){return({rifle:[120,20],scout:[180,35],turret:[160,45],extractor:[140,25]})[type]}
  function startBuild(type){if(state.gameOver||state.paused)return;if(type==='rifle'||type==='scout'){
      if(state.recruitCooldown>0){notify('RELAY QUEUE RECHARGING');return}if(!resource(costText(type)))return;
      state.recruitCooldown=3.5;const base=buildings.find(b=>b.type==='base');const u=makeUnit(type,base.x+rand(45,76),base.y+rand(-54,54));u.moveTarget={x:base.x+120,y:base.y+rand(-95,95)};log(`<span>NEW ${type==='rifle'?'SQUAD':'BUGGY'} deployed</span>`);notify(`${type==='rifle'?'RIFLE SQUAD':'SCOUT BUGGY'} DEPLOYED`);renderUI();return;
    }
    if(!resource(costText(type)))return;state.placing=type;ui['modal-title'].textContent=type==='turret'?'DEPLOY AUTOCANNON':'BUILD ALLOY EXTRACTOR';ui['modal-copy'].textContent='Confirm the order, then click a clear position on the battlefield.';ui['build-modal'].classList.add('open');
  }
