  document.querySelectorAll('.build-card').forEach(b=>b.addEventListener('click',()=>startBuild(b.dataset.build)));
  document.getElementById('pause-btn').onclick=togglePause;ui['speed-btn'].onclick=()=>{state.speed=state.speed===1?2:state.speed===2?.5:1;ui['speed-btn'].textContent=`${state.speed}×`;notify(`SIMULATION SPEED ${state.speed}×`)};
