  function togglePause(){if(state.gameOver)return;state.paused=!state.paused;ui['pause-overlay'].classList.toggle('show',state.paused);ui['pause-btn'].textContent=state.paused?'▶':'Ⅱ'}
  function chooseAt(p){let all=[...units,...buildings].filter(o=>o.team==='blue');all.sort((a,b)=>dist(p,a)-dist(p,b));const hit=all.find(o=>dist(p,o)<(o.size||14)+10);if(hit){state.selected=[hit];updateSelection();return}state.selected=[];updateSelection()}
  function updateSelection(){const selected=state.selected;units.forEach(u=>u.selected=selected.includes(u));buildings.forEach(b=>b.selected=selected.includes(b));if(!selected.length){ui['selection-label'].textContent='NO UNIT SELECTED';ui['selection-sub'].textContent='Select a unit or structure'}else{ui['selection-label'].textContent=selected.length>1?`${selected.length} UNITS SELECTED`:selected[0].name;ui['selection-sub'].textContent=selected[0].type==='base'?'Main operating base':selected[0].type==='turret'?'Defensive structure':selected[0].type==='extractor'?'Resource structure':'Ready for orders'}renderUI()}}
  function commandAt(p){if(state.placing){const type=state.placing;const base=buildings.find(b=>b.type==='base');if(p.x<base.x-30||p.x>920||p.y<65||p.y>WORLD.h-65||buildings.some(b=>dist(p,b)<b.size+30)){notify('INVALID BUILD LOCATION');return}const b=makeBuilding(type,p.x,p.y);state.placing=null;log(`${type==='turret'?'AUTOCANNON':'EXTRACTOR'} online`);notify(`${type==='turret'?'AUTOCANNON':'EXTRACTOR'} CONSTRUCTION COMPLETE`);renderUI();return}
    if(!state.selected.length)return;const enemy=[...units,...buildings].filter(o=>o.team==='red').sort((a,b)=>dist(p,a)-dist(p,b)).find(o=>dist(p,o)<o.size+20);state.selected.forEach(u=>{if(u.type==='base'||u.type==='turret'||u.type==='extractor')return;if(enemy){u.target=enemy;u.moveTarget=null}else{u.target=null;u.moveTarget={x:clamp(p.x+rand(-13,13),30,WORLD.w-30),y:clamp(p.y+rand(-13,13),30,WORLD.h-30)}}});if(enemy)notify('ATTACK ORDER CONFIRMED')}
  canvas.addEventListener('contextmenu',e=>e.preventDefault());
